    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'INVALID_INPUT' using detail = 'amount must be non-zero';
