CREATE OR REPLACE FUNCTION "public"."bump_template_prompt_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.body is distinct from old.body or new.model_params is distinct from old.model_params then
    new.version := old.version + 1;
    new.updated_at := now();
  else
    new.version := old.version;
  end if;
  return new;
end;
$$;


